-- INSPECTION ENGINE foundation schema + exact checklist seed
-- Generated from Master_Inspection_Checklist VINOD.docx (260 checkpoints).
create extension if not exists pgcrypto;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null,
  role text not null check (role in ('admin','inspector','mechanic','quality_controller','customer')),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.vehicles (
  id uuid primary key default gen_random_uuid(),
  registration_number text not null unique,
  make text not null,
  model text not null,
  variant text,
  vehicle_type text not null check (vehicle_type in ('motorcycle','scooter')),
  fuel_type text,
  engine_capacity text,
  manufacturing_year int,
  registration_year int,
  colour text,
  chassis_number text,
  engine_number text,
  odometer_reading_km numeric,
  owner_count int,
  has_abs boolean not null default false,
  has_parking_brake boolean not null default false,
  has_catalytic_converter boolean not null default false,
  source_dealer text,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles(id)
);

create table if not exists public.inspection_sections (
  section_no int primary key,
  name text not null
);

create table if not exists public.inspection_checkpoints (
  checkpoint_no int primary key,
  section_no int not null references public.inspection_sections(section_no),
  name text not null,
  classification text not null check (classification in ('Critical','Cosmetic','Data','Mixed')),
  assessment_method text not null,
  evidence_required text not null check (evidence_required in ('Photo','Video','Photo+Video','Not required')),
  active_for text not null default 'both' check (active_for in ('both','motorcycle','scooter')),
  is_conditional boolean not null default false,
  is_active boolean not null default true
);

create table if not exists public.inspections (
  id uuid primary key default gen_random_uuid(),
  vehicle_id uuid not null references public.vehicles(id),
  inspector_id uuid not null references public.profiles(id),
  status text not null default 'draft' check (status in ('draft','in_progress','submitted','repair_required','qc_pending','approved','rejected','cancelled')),
  started_at timestamptz not null default now(),
  submitted_at timestamptz,
  completed_at timestamptz,
  location_text text,
  gps_lat numeric,
  gps_lng numeric,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.checkpoint_results (
  id uuid primary key default gen_random_uuid(),
  inspection_id uuid not null references public.inspections(id) on delete cascade,
  checkpoint_no int not null references public.inspection_checkpoints(checkpoint_no),
  result_status text check (result_status in ('pass','fail','not_applicable','recorded')),
  cosmetic_score int check (cosmetic_score between 1 and 5),
  measured_value numeric,
  measured_unit text,
  recorded_value text,
  expected_value text,
  match_status text check (match_status in ('match','mismatch')),
  issue_description text,
  is_disclosed boolean,
  assessed_by uuid references public.profiles(id),
  assessed_at timestamptz,
  unique (inspection_id, checkpoint_no)
);

create table if not exists public.evidence (
  id uuid primary key default gen_random_uuid(),
  checkpoint_result_id uuid not null references public.checkpoint_results(id) on delete cascade,
  media_type text not null check (media_type in ('photo','video')),
  storage_path text not null,
  captured_at timestamptz not null default now(),
  uploaded_by uuid references public.profiles(id),
  metadata jsonb not null default '{}'::jsonb
);

create table if not exists public.repair_jobs (
  id uuid primary key default gen_random_uuid(),
  inspection_id uuid not null references public.inspections(id),
  checkpoint_result_id uuid references public.checkpoint_results(id),
  title text not null,
  description text,
  priority text not null default 'normal' check (priority in ('critical','high','normal','low')),
  status text not null default 'pending' check (status in ('pending','assigned','in_progress','completed','verified','cancelled')),
  assigned_mechanic_id uuid references public.profiles(id),
  estimated_cost numeric,
  actual_cost numeric,
  created_at timestamptz not null default now(),
  completed_at timestamptz
);

create table if not exists public.repair_updates (
  id uuid primary key default gen_random_uuid(),
  repair_job_id uuid not null references public.repair_jobs(id) on delete cascade,
  updated_by uuid references public.profiles(id),
  status text,
  note text,
  parts_used jsonb not null default '[]'::jsonb,
  evidence_paths jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.quality_reviews (
  id uuid primary key default gen_random_uuid(),
  inspection_id uuid not null references public.inspections(id),
  reviewer_id uuid not null references public.profiles(id),
  review_type text not null default 'repair_verification' check (review_type in ('repair_verification','blind_reaudit')),
  status text not null check (status in ('pending','approved','rejected','variance_flagged')),
  critical_variance_count int not null default 0,
  notes text,
  reviewed_at timestamptz not null default now()
);

create table if not exists public.vehicle_ratings (
  id uuid primary key default gen_random_uuid(),
  inspection_id uuid not null unique references public.inspections(id),
  cosmetic_score numeric check (cosmetic_score between 1 and 5),
  critical_failures int not null default 0,
  safety_clearance text not null check (safety_clearance in ('blocked','conditional','cleared')),
  sale_ready boolean not null default false,
  calculated_at timestamptz not null default now(),
  check (sale_ready = (safety_clearance = 'cleared' and critical_failures = 0))
);

create table if not exists public.vehicle_reports (
  id uuid primary key default gen_random_uuid(),
  inspection_id uuid not null unique references public.inspections(id),
  report_number text not null unique,
  public_token uuid not null default gen_random_uuid() unique,
  generated_at timestamptz not null default now(),
  published_at timestamptz
);

create table if not exists public.audit_logs (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references public.profiles(id),
  entity_type text not null,
  entity_id uuid,
  action text not null,
  before_data jsonb,
  after_data jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.inspector_dealer_assignments (
  id uuid primary key default gen_random_uuid(),
  inspector_id uuid not null references public.profiles(id),
  dealer_name text not null,
  last_assigned_at timestamptz,
  unique(inspector_id, dealer_name)
);

create table if not exists public.inspector_accuracy_events (
  id uuid primary key default gen_random_uuid(),
  inspector_id uuid not null references public.profiles(id),
  vehicle_id uuid not null references public.vehicles(id),
  inspection_id uuid not null references public.inspections(id),
  checkpoint_no int references public.inspection_checkpoints(checkpoint_no),
  event_type text not null check (event_type in ('post_sale_failure','blind_reaudit_variance','dispute_upheld')),
  details text,
  created_at timestamptz not null default now()
);

create index if not exists idx_inspections_vehicle on public.inspections(vehicle_id);
create index if not exists idx_inspections_inspector on public.inspections(inspector_id);
create index if not exists idx_checkpoint_results_inspection on public.checkpoint_results(inspection_id);
create index if not exists idx_repair_jobs_status on public.repair_jobs(status);
create index if not exists idx_quality_reviews_inspection on public.quality_reviews(inspection_id);

-- Checklist sections and checkpoints are seeded below.


-- Safety gate: only Critical failures block safety clearance; cosmetic score is separate.
create or replace function public.refresh_vehicle_rating(p_inspection_id uuid)
returns void language plpgsql security definer as $$
declare
  v_critical_failures int;
  v_cosmetic_score numeric;
  v_clearance text;
begin
  select count(*) into v_critical_failures
  from public.checkpoint_results r
  join public.inspection_checkpoints c on c.checkpoint_no = r.checkpoint_no
  where r.inspection_id = p_inspection_id
    and c.classification in ('Critical','Mixed')
    and r.result_status = 'fail';

  select round(avg(r.cosmetic_score)::numeric,2) into v_cosmetic_score
  from public.checkpoint_results r
  join public.inspection_checkpoints c on c.checkpoint_no = r.checkpoint_no
  where r.inspection_id = p_inspection_id
    and c.classification in ('Cosmetic','Mixed')
    and r.cosmetic_score is not null;

  v_clearance := case when v_critical_failures > 0 then 'blocked' else 'cleared' end;

  values (p_inspection_id,v_cosmetic_score,v_critical_failures,v_clearance,(v_critical_failures = 0))
  on conflict (inspection_id) do update set
    cosmetic_score=excluded.cosmetic_score,
    critical_failures=excluded.critical_failures,
    safety_clearance=excluded.safety_clearance,
    sale_ready=excluded.sale_ready,
    calculated_at=now();
end $$;

